def compute(vars):
    increase = vars["v1"] - vars["v2"]
    value = vars["v1"] + increase
    return {
        "value": value,
        "trace": {
            "increase": increase,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "index points"
            }
        }
    }
